insert into public.articles
  (slug, title, excerpt, category, cover_image, cover_image_alt, meta_description, content, status, published_at, author_name)
values
('en-uke-i-albir', 'En uke i Albir — slik var det', 'Femten padel-entusiaster fra Oslo. Sju dager med sol, padel og gode minner. Her er alt som skjedde.', 'Reiserapport', 'https://dbvnuoayzevtoaolhqxd.supabase.co/storage/v1/object/public/photos/action-evening.jpg', 'Spillere i aksjon på padelbane i Albir', 'Reiserapport fra Fera Padels tur til Albir, Costa Blanca. Sju dager med coaching, sol og padel — les hva som venter deg på en padelreise til Spania.', $json${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Klokken er halv seks om morgenen. Solen kryper over fjellene bak Albir og kaster et varmt, gyllent lys over de blå banene. Tre av deltakerne er allerede i gang med oppvarming. De andre er på vei. Ingen er sulne — men alle vet at frokost kan vente."}]},{"type":"paragraph","content":[{"type":"text","text":"Det er dag tre av syv. Vi er femten nordmenn på padeltur til Costa Blanca med Fera, og stemningen er en helt annen enn hjemme. Her finnes ingen unnskyldninger for å ikke spille. Det er bare padel, sol og folk som vil bli bedre."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ankomst og første inntrykk"}]},{"type":"paragraph","content":[{"type":"text","text":"Vi landet på Alicante lufthavn torsdag ettermiddag. Bussoverføringen til Albir tok under en time — langs kysten gjennom Benidorm og opp mot de hvite husene langs strandpromenaden. De første kommentarene på bussen handlet ikke om hotellet. De handlet om banene vi passerte langs veien."}]},{"type":"paragraph","content":[{"type":"text","text":"Albir er en liten, rolig by sammenlignet med nabobyen Benidorm. Det er nøyaktig det som gjør den perfekt for en padeltur. Ingen distraksjoner. Bare baner, gode restauranter og 300 meter fra hotellet til havet."}]},{"type":"paragraph","content":[{"type":"text","text":"Padelsenteret vi brukte hele uken hadde åtte baner under åpen himmel og to innendørs. På det meste spilte vi seks kamper på én dag. Det høres krevende ut. Det er krevende. Men på en måte ingen av oss hadde forventet."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Coaching som faktisk gjør en forskjell"}]},{"type":"paragraph","content":[{"type":"text","text":"André Schlyter holder morgenøkten. Én time med teknikk og taktikk, fulgt av to timers strukturert spill med rotasjon. Det er ikke et kurs. Det er ikke «tips og triks». Det er skikkelig trening."}]},{"type":"paragraph","content":[{"type":"text","text":"Dag én: bandejaen min er en vits. Dag fire: jeg treffer den tre av fem ganger. Det er ikke magi — det er repetisjon, tilbakemelding og rette vaner innøvd under solskin. André ser ting ved spillet ditt som du ikke selv ser, og han formidler det på en måte som faktisk sitter."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"«Jeg har spilt padel i to år og trodde jeg nærmet meg et platå. Etter fire dager med André skjønte jeg at jeg bare hadde begynt å forstå spillet.» — Kristian, deltaker fra Stavanger"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Livet mellom kampene"}]},{"type":"paragraph","content":[{"type":"text","text":"En padeltur er ikke bare padel. Det er frokosten ved bassenget hvor du analyserer gårsdagens kamper med folk du møtte for to dager siden. Det er tapas-restauranten på torget tirsdag kveld som anbefales av hotellet og lever opp til forventningene. Det er den spontane runden med doubles kl. 21 fordi ingen egentlig er klar for å stoppe."}]},{"type":"paragraph","content":[{"type":"text","text":"Gruppen vår bestod av folk i alderen 28–61. Noen kjente hverandre. De fleste gjorde ikke det. Innen dag to spilte det ingen rolle. Padel er en av de rareste og beste sosiale lim som finnes — du lærer folk raskt å kjenne når du jakter på den samme ballen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Praktisk info for deg som vurderer en tur"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reisetid fra Oslo:","marks":[{"type":"bold"}]},{"type":"text","text":" 3,5 timer til Alicante"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nivå:","marks":[{"type":"bold"}]},{"type":"text","text":" Alle nivåer er velkomne — coaching tilpasses gruppen"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inkludert:","marks":[{"type":"bold"}]},{"type":"text","text":" Hotell (halvpensjon), transport, baneleie og all coaching"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Utstyr:","marks":[{"type":"bold"}]},{"type":"text","text":" Vi anbefaler å ta med egen racket"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tidspunkt:","marks":[{"type":"bold"}]},{"type":"text","text":" Oktober–april er ideelt — 22–26 grader, ingen hete"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Kommer du på neste tur?"}]},{"type":"paragraph","content":[{"type":"text","text":"Vi tar med et begrenset antall deltakere på hver tur — nettopp fordi vi vil at alle skal få tid med coachen og at gruppen skal bli sammensveiset. Plass går fort. Av de femten som var med denne gangen, har ni allerede meldt seg på neste tur."}]},{"type":"paragraph","content":[{"type":"text","text":"Det sier egentlig alt."}]}]}$json$::jsonb, 'published', '2026-05-20T12:00:00.000Z', 'Fera Padel'),
('coaching-med-andre', 'Hva skjer egentlig på en coaching-økt med André?', 'André Schlyter er ikke en vanlig trener. Vi tok med kamera på banen for å vise deg hva du kan forvente.', 'Coaching', 'https://dbvnuoayzevtoaolhqxd.supabase.co/storage/v1/object/public/photos/coach-bullpadel.jpg', 'André Schlyter klar på padelbane', 'Hvordan er det å trene padel med André Schlyter? Vi beskriver coaching-metodikken, hva du lærer og hvorfor deltakerne på Fera Padels turer alltid kommer hjem som bedre spillere.', $json${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"De fleste treningsøkter du har hatt i padel ser sannsynligvis slik ut: noen slår noen baller, noen snakker om teknikk, og du går hjem uten å vite hva du faktisk skal jobbe med. Det er ikke slik André Schlyter driver coaching."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hvem er André?"}]},{"type":"paragraph","content":[{"type":"text","text":"André Schlyter er en av Norges beste padeltrenere og en av de mest kjente figurene i norsk padelmiljø. Han har spilt padel på elitenivå, trenet hundrevis av spillere — fra nybegynnere til turneringsspillere — og har en metodikk som skiller seg merkbart fra hva du finner på en lokal padelhall i Oslo."}]},{"type":"paragraph","content":[{"type":"text","text":"Det André gjør som er annerledes, er dette: han ser deg spille i ti minutter og gir deg én ting å jobbe med. Ikke fem. Én. Og den ene tingen er akkurat det som gir deg mest fremgang akkurat nå."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Slik ser en typisk morgenøkt ut"}]},{"type":"paragraph","content":[{"type":"text","text":"Klokken 8:00 er gruppen samlet på banen. André starter alltid med en kort gjennomgang — ikke en PowerPoint-presentasjon, men en samtale. Hva jobbet vi med i går? Hva kjente vi ikke på? Hva vil vi inn i dag?"}]},{"type":"paragraph","content":[{"type":"text","text":"Deretter: én time med strukturerte øvelser. Ikke basket. Ikke bare spille. Øvelser med konkrete mål — bandeja fra venstre, posisjonering i midtbanen, timing på smash. André er på banen med dere hele tiden. Han feeder baller, gir tilbakemelding i sanntid og lar deg prøve igjen til du kjenner at det sitter."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"«André er den eneste treneren jeg har hatt som faktisk greier å forklare "},{"type":"text","text":"hvorfor","marks":[{"type":"italic"}]},{"type":"text","text":" ting fungerer, ikke bare hva du skal gjøre. Det gjør at læringen sitter på en helt annen måte.» — Tonje, deltaker fra Bergen"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Etter morgenøkten er det frokost, en pause og så to-tre timers organisert spill med rotasjon. André ser på, stopper av og til og gir feedback. Det er ikke stressende — det er stimulerende."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hva du faktisk lærer på én uke"}]},{"type":"paragraph","content":[{"type":"text","text":"Det varierer selvsagt fra person til person, men på én uke med strukturert coaching ser vi gjennomgående forbedring på disse områdene:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Posisjonering","marks":[{"type":"bold"}]},{"type":"text","text":" — der spillet egentlig avgjøres"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bandejaen","marks":[{"type":"bold"}]},{"type":"text","text":" — den viktigste overgangsslagen i padel"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nettspill","marks":[{"type":"bold"}]},{"type":"text","text":" — offensivt og defensivt"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Taktisk lesning","marks":[{"type":"bold"}]},{"type":"text","text":" — forstå hva som kommer før det kommer"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Selvtillit under press","marks":[{"type":"bold"}]},{"type":"text","text":" — å holde hodet kaldt i viktige poeng"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Det handler ikke om å gå fra nivå 2 til nivå 5 på én uke. Det handler om å forstå spillet på en ny måte — og den forståelsen tar du med deg hjem og inn i hvert eneste spill du spiller etterpå."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Passer det for deg?"}]},{"type":"paragraph","content":[{"type":"text","text":"André tilpasser coachingen til gruppen. Har du spilt i tre måneder, er det noe annet som prioriteres enn om du har spilt i tre år. Det betyr at alle nivåer — fra nybegynnere til erfarne spillere — får reell verdi av ukens coaching."}]},{"type":"paragraph","content":[{"type":"text","text":"Det eneste som kreves av deg er at du er åpen for tilbakemelding og klar til å jobbe. Har du det, vil du bli overrasket over hvor mye du utvikler deg på én uke."}]},{"type":"paragraph","content":[{"type":"text","text":"Vil du oppleve det selv? "},{"type":"text","text":"Se kommende turer","marks":[{"type":"link","attrs":{"href":"/travels"}}]},{"type":"text","text":" og finn en dato som passer deg."}]}]}$json$::jsonb, 'published', '2026-05-12T12:00:00.000Z', 'Fera Padel'),
('derfor-elsker-vi-costa-blanca', 'Derfor elsker vi Costa Blanca', '300 soldager i året, fantastiske padelsentre og mat som slår alt. Vi forteller deg hvorfor Costa Blanca er det perfekte padelreisemålet.', 'Destinasjon', 'https://dbvnuoayzevtoaolhqxd.supabase.co/storage/v1/object/public/photos/palm-sunset.jpg', 'Padelbane med palmer og solnedgang i Costa Blanca', 'Costa Blanca er Europas padel-hovedstad. Her er de viktigste grunnene til at vi alltid kommer tilbake — og hvorfor du bør booke en padelreise til Spania.', $json${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vi har arrangert padelreiser til Costa Blanca siden starten. Vi har vurdert andre destinasjoner. Vi har alltid kommet tilbake til den samme konklusjonen: det finnes ingen bedre plass i Europa å dra på padeltur."}]},{"type":"paragraph","content":[{"type":"text","text":"Her er grunnene — og de er ikke tilfeldige."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Klima som er laget for padel"}]},{"type":"paragraph","content":[{"type":"text","text":"Costa Blanca har i gjennomsnitt over 300 soldager i året. Det betyr at du i praksis kan spille padel utendørs hele året — noe som er et konsept man ikke engang kan forestille seg for nordmenn som fryser gjennom ni måneder hjemme."}]},{"type":"paragraph","content":[{"type":"text","text":"Temperaturen om vinteren (oktober–april) ligger stabilt mellom 18 og 25 grader på dagtid. Det er ikke bare «akseptabelt» — det er ideelt for sport. Varmt nok til at kroppen er løs og klar, kjølig nok til at du ikke er utmattet etter én time på banen."}]},{"type":"paragraph","content":[{"type":"text","text":"Vi anbefaler alltid å legge turen til denne perioden. Høysesongen sommerstid er for varm for padel. Vinterprogrammet er når Costa Blanca er aller best."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tetthet av padelbaner du ikke finner andre steder"}]},{"type":"paragraph","content":[{"type":"text","text":"Padel ble populært i Spania lenge før det slo gjennom i Norge. I Benidorm-Albir-regionen finner du mer enn 40 padelsentre innen 20 kilometers radius. Mange av dem er av en kvalitet som ikke finnes i Norge — asfalterte baner, profesjonell belysning, kantine, treningsvegg og coacher tilgjengelig store deler av dagen."}]},{"type":"paragraph","content":[{"type":"text","text":"Det betyr at du aldri trenger å vente på bane. Det betyr at du kan spille fire timer om dagen uten problemer. Og det betyr at konkurransen mellom sentrene holder prisnivået lavt — en time på bane koster ofte halvparten av det du betaler hjemme."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Nivået på de lokale spillerne"}]},{"type":"paragraph","content":[{"type":"text","text":"Et av de mest undervurderte plussene ved å spille padel i Spania er hva du lærer av å møte spanjoler på banen. Det spanske padelmiljøet er på et helt annet nivå enn det norske — og det er ikke ment som kritikk av norsk padel, men som en anerkjennelse av at spanjolene har spilt sporten i generasjoner."}]},{"type":"paragraph","content":[{"type":"text","text":"Noen av de lokale spillerne du møter er pensjonerte herrer som har spilt padel i 30 år og ler vennlig av backhand-volleyen din — men også viser deg nøyaktig hvordan du skal gjøre det etterpå. Det er en del av kulturen, og det er ubetalelig for utviklingen din."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Mat, kultur og alt det andre"}]},{"type":"paragraph","content":[{"type":"text","text":"En padeltur er ikke bare padel. Det er den spanske frokosten ute på terrassen. Det er tapas med cerveza etter siste kamp. Det er å vandre langs strandpromenaden i Albir om kvelden, snakke om de beste øyeblikkene fra dagen, og planlegge morgendagens strategi med folk du bare har kjent i tre dager men som allerede føles som gamle venner."}]},{"type":"paragraph","content":[{"type":"text","text":"Costa Blanca er ikke en turist-fabrikk som Mallorca eller Gran Canaria. Spesielt Albir og L'Alfàs del Pi er rolige, familievennlige byer med autentisk spansk kultur, lave priser og folk som faktisk er glade for at du er der."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tilgjengelighet fra Norge"}]},{"type":"paragraph","content":[{"type":"text","text":"Alicante har direktefly fra Oslo (Gardermoen) og Bergen med Norwegian og Wizz Air. Flytid: under fire timer. Prisnivå: du finner gjerne tur-retur for 800–1500 kroner om du booker i god tid."}]},{"type":"paragraph","content":[{"type":"text","text":"Det er ingen grunn til å velge en dyr og logistisk krevende destinasjon når den beste padel-destinasjonen i Europa er nesten like nær som Praha."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Klar for turen?"}]},{"type":"paragraph","content":[{"type":"text","text":"Vi arrangerer turer til Costa Blanca gjennom hele vinter- og vårsesongen. Alle inkluderer hotell, coaching med André, baneleie og transport fra flyplassen. Du ordner kun flybilletten selv."}]},{"type":"paragraph","content":[{"type":"text","text":"Se alle kommende turer →","marks":[{"type":"link","attrs":{"href":"/travels"}}]}]}]}$json$::jsonb, 'published', '2026-05-03T12:00:00.000Z', 'Fera Padel')
